        #1; if (tc !== 1'b0) begin errors = errors + 1; $display("FAIL: expected tc=0 for count=1"); end

        @(posedge clk); // count becomes 0
        #1; if (tc !== 1'b1) begin errors = errors + 1; $display("FAIL: expected tc=1 when count hits 0"); end

        // Test 3: Saturation at 0 (should not underflow or decrement below 0)
        @(posedge clk);
        #1; if (tc !== 1'b1) begin errors = errors + 1; $display("FAIL: tc should stay 1 at 0"); end

        // Test 4: Asynchronous/Synchronous reload while counting down
        @(posedge clk);
        load = 1;
        data = 10'd2;
        @(posedge clk);
        load = 0; // count = 2

        #1; if (tc !== 1'b0) begin errors = errors + 1; end

        @(posedge clk); // count = 1
        // Reload *while* counting (before reaching 0)
        load = 1;
        data = 10'd5;
        @(posedge clk);
        load = 0; // count should now be 5, NOT 0

        #1; if (tc !== 1'b0) begin errors = errors + 1; $display("FAIL: reload while active failed"); end

        // Check that it takes 5 cycles to hit 0 again
        repeat(5) @(posedge clk);
        #1; 
        if (tc !== 1'b1) begin 
            errors = errors + 1; 
            $display("FAIL: reloaded with 5, did not reach tc=1 after 5 cycles"); 
        end

        // Finish reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
